prompt:
Create unit `tasks` and implement `div_floor`: for |a| <= 1000000000 and 1 <= b <= 1000000000, return a divided by b rounded toward negative infinity (note that `/` rounds toward zero). The contract must state r * b <= a < r * b + b.

Required signature (in unit `tasks`):
fn div_floor(a: i64, b: i64) -> (r: i64)

reference.code:
spec fn div_args(a: i64, b: i64) -> bool { -1000000000 <= a && a <= 1000000000 && 1 <= b && b <= 1000000000 }

spec fn floor_ok(a: i64, b: i64, r: i64) -> bool { r * b <= a && a < r * b + b }

#[effects(pure)]
#[uses(div_args, floor_ok)]
fn div_floor(a: i64, b: i64) -> (r: i64)
    requires div_args(a, b),
    ensures floor_ok(a, b, r),
{
    let q: i64 = a / b;
    if a % b != 0 && a < 0 {
        q - 1
    } else {
        q
    }
}

